import pytesseract
from PIL import Image
import os
import re
import json
from datetime import datetime

def extract_date(text):
    patterns = [
        r'\b\d{2}[/-]\d{2}[/-]\d{4}\b',
        r'\b\d{4}[/-]\d{2}[/-]\d{2}\b',
        r'\b\d{2}\.\d{2}\.\d{4}\b',
    ]

    all_matches = []
    for pattern in patterns:
        for m in re.finditer(pattern, text):
            all_matches.append(m)
    all_matches.sort(key=lambda x: x.start())

    for m in all_matches:
        date_s = m.group(0)
        # Try common formats. DD/MM/YYYY is preferred for RM receipts.
        formats = [
            '%d/%m/%Y', '%d-%m-%Y', '%d.%m.%Y',
            '%Y/%m/%d', '%Y-%m-%d',
            '%m/%d/%Y', '%m-%d-%Y', '%m.%d.%Y'
        ]
        for fmt in formats:
            try:
                dt = datetime.strptime(date_s, fmt)
                if 1990 < dt.year < 2030:
                    return dt.strftime('%Y-%m-%d')
            except ValueError:
                continue
    return None

def extract_total(text):
    lines = text.split('\n')
    lines = [line.strip() for line in lines if line.strip()]

    priority_keywords = [
        'GRAND TOTAL', 'TOTAL RM', 'TOTAL: RM', 'TOTAL AMOUNT',
        'TOTAL', 'AMOUNT', 'TOTAL DUE', 'AMOUNT DUE', 'BALANCE DUE', 'NETT TOTAL', 'NET TOTAL'
    ]

    exclusion_keywords = [
        'SUBTOTAL', 'SUB TOTAL', 'TAX', 'GST', 'SST', 'DISCOUNT', 'CHANGE', 'CASH TENDERED'
    ]

    for kw in priority_keywords:
        # First pass: look for keyword and amount on the same line
        for i, line in enumerate(lines):
            if kw.upper() in line.upper():
                skip = False
                for ex in exclusion_keywords:
                    if ex.upper() in line.upper():
                        skip = True
                        break
                if skip:
                    continue

                amount_match = re.search(r'(\d{1,3}(?:,\d{3})*\.\d{2})', line)
                if amount_match:
                    return amount_match.group(1).replace(',', '')

        # Second pass: look for keyword and amount on the next line
        for i, line in enumerate(lines):
            if kw.upper() in line.upper():
                skip = False
                for ex in exclusion_keywords:
                    if ex.upper() in line.upper():
                        skip = True
                        break
                if skip:
                    continue

                if i + 1 < len(lines):
                    next_line = lines[i+1]
                    amounts = re.findall(r'(\d{1,3}(?:,\d{3})*\.\d{2})', next_line)
                    if amounts:
                        # Use the last number on that next line
                        return amounts[-1].replace(',', '')
    return None

def main():
    img_dir = 'dataset/img'
    files = sorted([f for f in os.listdir(img_dir) if f.endswith('.jpg')])
    results = []
    for filename in files:
        path = os.path.join(img_dir, filename)
        try:
            text = pytesseract.image_to_string(Image.open(path))
            date = extract_date(text)
            total = extract_total(text)
            results.append({
                'filename': filename,
                'date': date,
                'total_amount': total
            })
        except Exception as e:
            results.append({
                'filename': filename,
                'date': None,
                'total_amount': None
            })

    print(json.dumps(results, indent=2))

if __name__ == '__main__':
    main()

