import pytesseract
from PIL import Image
import os
import re
import json
from datetime import datetime

def extract_date(text):
    # More flexible date patterns
    patterns = [
        r'\b\d{1,2}[/-]\d{1,2}[/-]\d{2,4}\b',
        r'\b\d{4}[/-]\d{1,2}[/-]\d{1,2}\b',
        r'\b\d{1,2}\.\d{1,2}\.\d{2,4}\b',
    ]

    all_matches = []
    for pattern in patterns:
        for m in re.finditer(pattern, text):
            all_matches.append(m)
    all_matches.sort(key=lambda x: x.start())

    formats = [
        '%d/%m/%Y', '%d-%m-%Y', '%d.%m.%Y',
        '%Y/%m/%d', '%Y-%m-%d',
        '%d/%m/%y', '%d-%m-%y', '%d.%m.%y',
        '%y/%m/%d', '%y-%m-%d',
        '%m/%d/%Y', '%m-%d-%Y', '%m.%d.%Y',
        '%m/%d/%y', '%m-%d/%y', '%m.%d.%y'
    ]

    for m in all_matches:
        date_s = m.group(0)
        for fmt in formats:
            try:
                dt = datetime.strptime(date_s, fmt)
                if 1990 < dt.year < 2030:
                    return dt.strftime('%Y-%m-%d')
            except ValueError:
                continue
    return None

def clean_amount(s):
    # Remove commas
    s = s.replace(',', '')
    # Handle common OCR errors in decimal part
    # Look for a dot followed by 2 characters that might be digits
    match = re.search(r'(\d+)\.([0-9uUoO]{2})', s)
    if match:
        d = match.group(1)
        c = match.group(2).replace('u','0').replace('U','0').replace('o','0').replace('O','0')
        return f"{d}.{c}"

    # Also handle the case where there are more than 2 digits after dot, take first 2
    match = re.search(r'(\d+)\.([0-9uUoO]{2,})', s)
    if match:
        d = match.group(1)
        c = match.group(2)[:2].replace('u','0').replace('U','0').replace('o','0').replace('O','0')
        return f"{d}.{c}"

    # Try simple \d+.\d{2}
    match = re.search(r'(\d+\.\d{2})', s)
    if match:
        return match.group(1)

    return None

def extract_total(text):
    lines = text.split('\n')
    lines = [line.strip() for line in lines if line.strip()]

    priority_keywords = [
        'GRAND TOTAL', 'TOTAL RM', 'TOTAL: RM', 'TOTAL AMOUNT',
        'TOTAL', 'AMOUNT', 'TOTAL DUE', 'AMOUNT DUE', 'BALANCE DUE', 'NETT TOTAL', 'NET TOTAL'
    ]

    exclusion_keywords = [
        'SUBTOTAL', 'SUB TOTAL', 'TAX', 'GST', 'SST', 'DISCOUNT', 'CHANGE', 'CASH TENDERED'
    ]

    for kw in priority_keywords:
        # First pass: keyword and amount on same line
        for i, line in enumerate(lines):
            if kw.upper() in line.upper():
                skip = False
                for ex in exclusion_keywords:
                    if ex.upper() in line.upper():
                        skip = True
                        break
                if skip:
                    continue

                # Use clean_amount to find value
                amount = clean_amount(line)
                if amount:
                    return amount

        # Second pass: keyword on this line, amount on next line
        for i, line in enumerate(lines):
            if kw.upper() in line.upper():
                skip = False
                for ex in exclusion_keywords:
                    if ex.upper() in line.upper():
                        skip = True
                        break
                if skip:
                    continue

                if i + 1 < len(lines):
                    next_line = lines[i+1]
                    # We want the LAST amount on the next line
                    # Let's find all candidates
                    amounts = re.findall(r'(\d+[\.,][0-9uUoO]{2,})', next_line)
                    if amounts:
                        amt = clean_amount(amounts[-1].replace(',', '.'))
                        if amt:
                            return amt
    return None

def main():
    img_dir = 'dataset/img'
    files = sorted([f for f in os.listdir(img_dir) if f.endswith('.jpg')])
    results = []
    for filename in files:
        path = os.path.join(img_dir, filename)
        try:
            text = pytesseract.image_to_string(Image.open(path))
            date = extract_date(text)
            total = extract_total(text)
            results.append({
                'filename': filename,
                'date': date,
                'total_amount': total
            })
        except Exception as e:
            results.append({
                'filename': filename,
                'date': None,
                'total_amount': None
            })

    print(json.dumps(results, indent=2))

